using Azure;using Azure.Messaging.ServiceBus;using System.Text.Json;using Microsoft.Extensions.Options;
namespace EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;
public sealed class ServiceBusOptions{public string FullyQualifiedNamespace{get;set;}="";public string ConnectionString{get;set;}="";public int MaxConcurrentCalls{get;set;}=8;}
public interface IMessagePublisher{Task PublishAsync<T>(string topic,T message,string correlationId,CancellationToken ct=default);}
public sealed class ServiceBusPublisher:IMessagePublisher,IAsyncDisposable{readonly ServiceBusClient client;readonly JsonSerializerOptions json=new(JsonSerializerDefaults.Web);public ServiceBusPublisher(IOptions<ServiceBusOptions> o){client=!string.IsNullOrWhiteSpace(o.Value.ConnectionString)?new(o.Value.ConnectionString):new(o.Value.FullyQualifiedNamespace,new DefaultAzureCredential());}public async Task PublishAsync<T>(string topic,T message,string correlationId,CancellationToken ct=default){await using var sender=client.CreateSender(topic);var m=new ServiceBusMessage(JsonSerializer.Serialize(message,json)){ContentType="application/json",CorrelationId=correlationId,MessageId=Guid.NewGuid().ToString("N")};m.ApplicationProperties["schemaVersion"]="1";await sender.SendMessageAsync(m,ct);}public ValueTask DisposeAsync()=>client.DisposeAsync();}